<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsToMany;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;
use Illuminate\Support\Str;

class Destination extends Model
{
    use HasFactory, SoftDeletes;

    // signing_secret is generated by the relay, never mass-assigned from a form.
    protected $fillable = [
        'name',
        'url',
        'active',
    ];

    protected $casts = [
        'active' => 'boolean',
        'signing_secret' => 'encrypted',
    ];

    protected static function booted(): void
    {
        static::creating(function (Destination $destination) {
            if (empty($destination->signing_secret)) {
                $destination->signing_secret = static::generateSigningSecret();
            }
        });
    }

    /**
     * A fresh outbound signing secret. hook-relay signs every forwarded delivery
     * with the destination's secret so the consumer can verify its origin.
     */
    public static function generateSigningSecret(): string
    {
        return 'whsec_'.Str::random(40);
    }

    /**
     * Replace the signing secret, invalidating the previous one immediately.
     * Returns the new secret so the caller can show it once.
     */
    public function rotateSigningSecret(): string
    {
        $secret = static::generateSigningSecret();
        $this->forceFill(['signing_secret' => $secret])->save();

        return $secret;
    }

    public function sources(): BelongsToMany
    {
        return $this->belongsToMany(Source::class, 'source_destination');
    }

    public function deliveries(): HasMany
    {
        return $this->hasMany(Delivery::class);
    }
}
